package vn.covie.notifications.application; import com.fasterxml.jackson.databind.ObjectMapper; import java.nio.charset.StandardCharsets; import java.util.Base64; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Component; import vn.covie.shared.web.*;
@Component public class NotificationCursorCodec { private final ObjectMapper json; public NotificationCursorCodec(ObjectMapper json){this.json=json;} public String encode(NotificationCursor cursor){try{return Base64.getUrlEncoder().withoutPadding().encodeToString(json.writeValueAsBytes(cursor));}catch(Exception e){throw new IllegalArgumentException(e);}} public NotificationCursor decode(String value){if(value==null||value.isBlank())return null;try{var c=json.readValue(Base64.getUrlDecoder().decode(value.getBytes(StandardCharsets.US_ASCII)),NotificationCursor.class);if(c.v()!=1||c.createdAt()==null||c.notificationId()==null)throw invalid();return c;}catch(ApiException e){throw e;}catch(Exception e){throw invalid();}} private static ApiException invalid(){return new ApiException(ErrorCode.VALIDATION_FAILED,HttpStatus.UNPROCESSABLE_ENTITY,"Notification cursor is invalid.");}}
